# fill background cells between any two same-color 9 points in each row or column
out=[row[:] for row in grid]
for r,row in enumerate(grid):
    cs=[c for c,v in enumerate(row) if v==9]
    if len(cs)>1:
        for c in range(min(cs),max(cs)+1):
            if out[r][c]==6: out[r][c]=2
